import { defineConfig, type UserConfig } from "tsdown";
const existing = () => ({ name: "kept" });
const workerConfig = (entry: string): UserConfig => ({
  entry,
  plugins: [existing()] as unknown as UserConfig["plugins"],
});
export default defineConfig([
  { entry: ["src/index.ts"], format: "esm" },
  workerConfig("src/worker.ts"),
  { entry: "src/dev.ts", plugins: [existing()], dts: false },
]);
